//lxrtxdy!
#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = 1000000000;
const int MAX_NODES = 7100;

struct DinicMaxFlow {
    struct Edge {
        int from, to;
        ll flow, cap;
    };

    int s, t;
    vector<Edge> edges;
    vector<int> adj[MAX_NODES];
    int level[MAX_NODES], pos[MAX_NODES];

    void clear() {
        edges.clear();
        for (int i = 0; i < MAX_NODES; ++i) adj[i].clear();
    }

    void add_edge(int u, int v, ll capacity) {
        edges.push_back({u, v, 0, capacity});
        edges.push_back({v, u, 0, 0});
        adj[u].push_back(edges.size() - 2);
        adj[v].push_back(edges.size() - 1);
    }

    bool create_levels() {
        memset(level, -1, sizeof(level));
        queue<int> q;
        q.push(s);
        level[s] = 0;

        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int idx : adj[u]) {
                auto &e = edges[idx];
                if (e.cap > e.flow && level[e.to] == -1) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] != -1;
    }

    ll send_flow(int u, ll flow_limit) {
        if (u == t || !flow_limit) return flow_limit;
        ll pushed = 0;
        for (int &i = pos[u]; i < (int)adj[u].size(); ++i) {
            int idx = adj[u][i];
            auto &e = edges[idx];
            if (level[e.to] == level[u] + 1 && e.cap > e.flow) {
                ll delta = send_flow(e.to, min(flow_limit, e.cap - e.flow));
                if (delta) {
                    e.flow += delta;
                    edges[idx ^ 1].flow -= delta;
                    pushed += delta;
                    flow_limit -= delta;
                    if (!flow_limit) break;
                }
            }
        }
        return pushed;
    }

    ll solve() {
        ll total = 0;
        while (create_levels()) {
            memset(pos, 0, sizeof(pos));
            ll delta;
            while ((delta = send_flow(s, INF)) > 0)
                total += delta;
        }
        return total;
    }
};

DinicMaxFlow flow;
char grid1[14][14], grid2[14][14];
bool visited_cell[14][14];
int distance_map[14][14];
int N, T;
int dest_node[103];

void multi_source_bfs(int sx, int sy) {
    for (int i = 0; i < 14; ++i)
        fill(distance_map[i], distance_map[i] + 14, 111);
    queue<tuple<int, int, int>> q;
    distance_map[sx][sy] = 0;
    q.emplace(sx, sy, 0);

    const int dr[4] = {1, 0, 0, -1};
    const int dc[4] = {0, 1, -1, 0};

    while (!q.empty()) {
        auto [r, c, d] = q.front(); q.pop();
        if (visited_cell[r][c]) continue;
        visited_cell[r][c] = true;
        distance_map[r][c] = d;

        for (int i = 0; i < 4; ++i) {
            int nr = r + dr[i], nc = c + dc[i];
            if (nr >= 1 && nr <= N && nc >= 1 && nc <= N &&
                !visited_cell[nr][nc] && grid1[nr][nc] != 'Y') {
                q.emplace(nr, nc, d + 1);
            }
        }
    }
}

int node_id(int t, int r, int c) {
    return t * N * N + (r - 1) * N + c;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> T;
    for (int i = 1; i <= N; ++i) cin >> (grid1[i] + 1);
    for (int i = 1; i <= N; ++i) cin >> (grid2[i] + 1);

    flow.clear();
    flow.s = 0;
    flow.t = MAX_NODES - 2;

    int start_r = 0, start_c = 0;
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            if (grid1[i][j] == 'Z') {
                start_r = i; start_c = j;
                break;
            }
        }
    }

    for (int i = 1; i <= N * N; ++i)
        dest_node[i] = MAX_NODES - 3 - (N * N - i);

    multi_source_bfs(start_r, start_c);

    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            if (isdigit(grid1[i][j]))
                flow.add_edge(flow.s, node_id(0, i, j), grid1[i][j] - '0');
            if (isdigit(grid2[i][j]))
                flow.add_edge(dest_node[node_id(0, i, j)], flow.t, grid2[i][j] - '0');
            flow.add_edge(node_id(0, i, j), dest_node[node_id(0, i, j)], INF);
        }
    }

    const int dr[4] = {1, 0, 0, -1};
    const int dc[4] = {0, 1, -1, 0};

    for (int t = 1; t <= T; ++t) {
        for (int r = 1; r <= N; ++r) {
            for (int c = 1; c <= N; ++c) {
                if (grid1[r][c] == 'Y' || grid1[r][c] == 'Z') continue;
                for (int d = 0; d < 4; ++d) {
                    int nr = r + dr[d], nc = c + dc[d];
                    if (nr >= 1 && nr <= N && nc >= 1 && nc <= N &&
                        grid1[nr][nc] != 'Y' && grid1[nr][nc] != 'Z' &&
                        distance_map[r][c] >= t && distance_map[nr][nc] >= t) {
                        flow.add_edge(node_id(t - 1, nr, nc), node_id(t, r, c), INF);
                    }
                }
                flow.add_edge(node_id(t, r, c), dest_node[node_id(0, r, c)], INF);
            }
        }
    }

    cout << flow.solve() << '\n';
    return 0;
}
